css:
.retailops-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.retailops-sim-header {
    background: linear-gradient(135deg, #1a237e 0%, #283593 50%, #3949ab 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(26,35,126,0.3);
    text-align: center;
}

.retailops-sim-header h1 {
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 8px;
}

.retailops-sim-header p {
    font-size: 0.95rem;
    opacity: 0.85;
    margin: 0;
}

.retailops-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #455a64;
    margin-bottom: 20px;
    font-weight: 600;
}

.retailops-sim-period-counter span {
    margin: 0 3px;
}

.retailops-sim-event-panel {
    background: linear-gradient(135deg, #fff3e0 0%, #ffe0b2 100%);
    border-left: 5px solid #ff9800;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 24px;
    display: flex;
    align-items: flex-start;
    gap: 15px;
    box-shadow: 0 4px 12px rgba(255,152,0,0.15);
}

.retailops-sim-event-badge {
    font-size: 2rem;
    flex-shrink: 0;
}

.retailops-sim-event-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #e65100;
    margin-bottom: 6px;
}

.retailops-sim-event-text {
    font-size: 0.9rem;
    color: #4e342e;
    margin: 0;
    line-height: 1.5;
}

.retailops-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.retailops-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 16px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
}

.retailops-sim-status-card:hover {
    transform: translateY(-4px);
}

.retailops-sim-card-highlight {
    background: linear-gradient(135deg, #e8eaf6 0%, #c5cae9 100%);
    border: 2px solid #3f51b5;
}

.retailops-sim-label {
    color: #666;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.retailops-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a237e;
}

.retailops-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.retailops-sim-briefing h4 {
    color: #1a237e;
    font-size: 1rem;
    font-weight: 700;
    margin-bottom: 10px;
}

.retailops-sim-briefing p {
    color: #37474f;
    font-size: 0.9rem;
    line-height: 1.6;
    margin: 0;
}

.retailops-sim-metrics-bar {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}

.retailops-sim-metric-item {
    background: white;
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
}

.retailops-sim-metric-label {
    color: #78909c;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
}

.retailops-sim-metric-val {
    font-weight: 700;
    font-size: 1.05rem;
    color: #263238;
}

.retailops-sim-controls {
    background: white;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.retailops-sim-controls h3 {
    color: #1a237e;
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 20px;
    text-align: center;
}

.retailops-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}

.retailops-sim-decision-group {
    background: #f5f7fa;
    border-radius: 10px;
    padding: 16px;
}

.retailops-sim-decision-group label {
    display: block;
    font-weight: 600;
    font-size: 0.88rem;
    color: #37474f;
    margin-bottom: 8px;
}

.retailops-sim-decision-group select,
.retailops-sim-decision-group input[type="range"] {
    width: 100%;
}

.retailops-sim-hint {
    display: block;
    color: #90a4ae;
    font-size: 0.75rem;
    margin-top: 6px;
    font-style: italic;
}

.retailops-sim-range-display {
    text-align: center;
    font-size: 0.9rem;
    font-weight: 600;
    color: #1a237e;
    margin-top: 4px;
}

.retailops-sim-submit-btn {
    background: linear-gradient(135deg, #1a237e 0%, #3949ab 100%);
    border: none;
    font-size: 1.1rem;
    padding: 14px;
    border-radius: 12px;
    font-weight: 700;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 12px rgba(26,35,126,0.3);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.retailops-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(26,35,126,0.4);
}

.retailops-sim-history {
    background: white;
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    overflow-x: auto;
}

.retailops-sim-history h4 {
    color: #1a237e;
    font-size: 1rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.retailops-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}

.retailops-sim-chart-box {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 280px;
}

@media (max-width: 768px) {
    .retailops-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .retailops-sim-decision-grid {
        grid-template-columns: 1fr;
    }
    .retailops-sim-charts {
        grid-template-columns: 1fr;
    }
    .retailops-sim-header h1 {
        font-size: 1.3rem;
    }
    .retailops-sim-value {
        font-size: 1.2rem;
    }
}

@media (max-width: 480px) {
    .retailops-sim-status-cards {
        grid-template-columns: 1fr;
    }
    .retailops-sim-metrics-bar {
        grid-template-columns: repeat(2, 1fr);
    }
}

