(function() {
    'use strict';

    class RetailOpsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'RetailOps: Multi-Channel Retail Management';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Round 1: Establish Your Strategy',
                    description: 'You manage a consumer electronics retail chain with 15-20 physical stores and a growing e-commerce channel across two geographies: Andina Metro (urban, high digital adoption) and Andina Regional (mid-tier cities, lower digital penetration). The total market is USD 4.2 billion annually, growing 8-10% per year. Your chain currently holds 20% market share. Set your initial strategy across pricing, assortment, inventory, store operations, online investment, and vendor partnerships.',
                    event: null,
                    marketGrowth: 0.007,
                    showSmartHome: false
                },
                {
                    title: 'Round 2: Competitive Price War',
                    description: 'TechZone, the market leader (31% share), has announced aggressive price cuts of 12-15% on laptops and smartphones. Customers are flocking to their stores. You must decide: match their prices and sacrifice margin to protect market share, or differentiate on service and experience while accepting some share loss. This is the fundamental retail tension between margin preservation and market share defense.',
                    event: 'price_war',
                    marketGrowth: 0.006,
                    showSmartHome: false
                },
                {
                    title: 'Round 3: New Category Disruption',
                    description: 'Smart home devices (speakers, hubs, displays) have emerged as a breakout category with 40% growth potential and 45% gross margin, significantly higher than traditional consumer electronics. You can now choose "Smart Home" as your category focus to reallocate inventory and shelf space. Early movers capture premium margin, but reallocation means cannibalizing shelf space from established categories. The price war from Round 2 is easing as competitors adjust.',
                    event: 'new_category',
                    marketGrowth: 0.008,
                    showSmartHome: true
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000000,
                    marketShare: 20,
                    customerSatisfaction: 70,
                    onlinePenetration: 18,
                    inventoryTurnover: 5.0,
                    markdownRate: 18,
                    sellThrough: 70,
                    gmroi: 250,
                    crpiScore: 0,
                    totalRevenue: 0,
                    totalGrossMargin: 0,
                    totalNetProfit: 0,
                    revenueHistory: [],
                    marginHistory: [],
                    marketShareHistory: [],
                    crpiHistory: [],
                    satisfactionHistory: [],
                    onlinePenHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    pricingStrategy: 0,
                    categoryFocus: 'balanced',
                    safetyStock: 'standard',
                    storeInvestment: 5,
                    onlineInvestment: 5,
                    vendorStrategy: 'co-marketing'
                };
            }
            this._updateBriefing(state);
            this._setupSliderListeners();
        }

        _setupSliderListeners() {
            var storeSlider = document.getElementById('storeInput');
            var storeLabel = document.getElementById('storeValueLabel');
            if (storeSlider && storeLabel) {
                storeSlider.addEventListener('input', function() {
                    storeLabel.textContent = storeSlider.value;
                });
            }
            var onlineSlider = document.getElementById('onlineInput');
            var onlineLabel = document.getElementById('onlineValueLabel');
            if (onlineSlider && onlineLabel) {
                onlineSlider.addEventListener('input', function() {
                    onlineLabel.textContent = onlineSlider.value;
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.description;

            var eventPanel = document.getElementById('eventPanel');
            var eventBadge = document.getElementById('eventBadge');
            var eventTitle = document.getElementById('eventTitle');
            var eventText = document.getElementById('eventText');

            if (round.event === 'price_war' && eventPanel) {
                eventPanel.style.display = 'flex';
                if (eventBadge) eventBadge.innerHTML = '🔥';
                if (eventTitle) eventTitle.innerHTML = window.mySimulation ? window.mySimulation.t('event_pricewar_title') : 'Price War Alert';
                if (eventText) eventText.innerHTML = window.mySimulation ? window.mySimulation.t('event_pricewar_desc') : 'TechZone has slashed prices 12-15% on key categories. How will you respond?';
            } else if (round.event === 'new_category' && eventPanel) {
                eventPanel.style.display = 'flex';
                if (eventBadge) eventBadge.innerHTML = '🏠';
                if (eventTitle) eventTitle.innerHTML = window.mySimulation ? window.mySimulation.t('event_newcat_title') : 'New Category: Smart Home';
                if (eventText) eventText.innerHTML = window.mySimulation ? window.mySimulation.t('event_newcat_desc') : 'Smart home devices offer 45% gross margin and 40% growth. Will you reallocate?';
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }

            var smartHomeOpt = document.getElementById('smartHomeOption');
            if (smartHomeOpt) {
                smartHomeOpt.style.display = round.showSmartHome ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            var pricingEl = document.getElementById('pricingInput');
            if (pricingEl) decisions.pricingStrategy = parseFloat(pricingEl.value);

            var categoryEl = document.getElementById('categoryInput');
            if (categoryEl) decisions.categoryFocus = categoryEl.value;

            var safetyEl = document.getElementById('safetyStockInput');
            if (safetyEl) decisions.safetyStock = safetyEl.value;

            var storeEl = document.getElementById('storeInput');
            if (storeEl) decisions.storeInvestment = parseInt(storeEl.value);

            var onlineEl = document.getElementById('onlineInput');
            if (onlineEl) decisions.onlineInvestment = parseInt(onlineEl.value);

            var vendorEl = document.getElementById('vendorInput');
            if (vendorEl) decisions.vendorStrategy = vendorEl.value;

            if (decisions.categoryFocus === 'smart_home' && window.mySimulation && window.mySimulation.state.currentPeriod < 3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('smart_home_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var pricingAdj = parseFloat(d.pricingStrategy) || 0;
            var safetyStock = d.safetyStock || 'standard';
            var storeInv = parseInt(d.storeInvestment) || 5;
            var onlineInv = parseInt(d.onlineInvestment) || 5;
            var catFocus = d.categoryFocus || 'balanced';
            var vendorStrat = d.vendorStrategy || 'co-marketing';

            var priceVolumeMult = 1.0 + (-pricingAdj * 0.018);

            var marginAdj = pricingAdj * 0.007;

            var stockEffects = {
                low:      { availability: 0.88, carrying: 50000,  markdownAdj: -0.04, turnoverAdj: 1.5 },
                standard: { availability: 0.96, carrying: 100000, markdownAdj: 0,     turnoverAdj: 0 },
                high:     { availability: 1.00, carrying: 180000, markdownAdj: 0.04,  turnoverAdj: -1.2 }
            };
            var stockEff = stockEffects[safetyStock] || stockEffects['standard'];

            var storeConversion = 0.85 + (storeInv * 0.03);
            var storeCost = storeInv * 65000;

            var onlinePenetrationCalc = Math.min(45, 10 + (onlineInv * 2.5));
            var onlineCost = onlineInv * 45000;
            var onlineMarginPenalty = onlinePenetrationCalc * 0.001;

            var categoryBonus = 1.0;
            if (catFocus === 'smart_home' && period >= 3) {
                categoryBonus = 1.06;
                marginAdj += 0.035;
            } else if (catFocus !== 'balanced') {
                categoryBonus = 1.025;
            }

            var vendorMarginBonus = 0;
            var vendorRevenueMult = 1.0;
            var vendorCashBonus = 0;
            if (vendorStrat === 'exclusive') {
                vendorMarginBonus = 0.025;
                vendorRevenueMult = 0.97;
            } else if (vendorStrat === 'co-marketing') {
                vendorRevenueMult = 1.03;
            } else if (vendorStrat === 'captaincy') {
                vendorMarginBonus = 0.015;
            } else if (vendorStrat === 'financing') {
                vendorCashBonus = 200000;
            }

            var growthMult = 1.0 + round.marketGrowth;

            var eventImpact = 1.0;
            var eventMarginImpact = 0;
            if (period === 2) {
                if (pricingAdj >= 0) {
                    eventImpact = 0.92;
                } else {
                    eventImpact = 1.02;
                    eventMarginImpact = -0.02;
                }
            }
            if (period === 3 && catFocus !== 'smart_home') {
                eventImpact *= 0.97;
            }

            var baseRevenue = 8000000;
            var revenue = Math.round(baseRevenue * priceVolumeMult * storeConversion * stockEff.availability * categoryBonus * vendorRevenueMult * growthMult * eventImpact);

            var grossMarginPct = 0.38 + marginAdj + vendorMarginBonus - onlineMarginPenalty - (stockEff.markdownAdj * 0.1) + eventMarginImpact;
            grossMarginPct = Math.max(0.20, Math.min(0.50, grossMarginPct));
            var grossMargin = Math.round(revenue * grossMarginPct);

            var totalOpCost = storeCost + onlineCost + stockEff.carrying;
            var netProfit = grossMargin - totalOpCost;

            ds.cash += netProfit + vendorCashBonus;
            ds.totalRevenue += revenue;
            ds.totalGrossMargin += grossMargin;
            ds.totalNetProfit += netProfit;

            var shareChange = 0;
            if (revenue > 8500000) shareChange += 1.5;
            else if (revenue < 7500000) shareChange -= 1.5;
            if (grossMarginPct > 0.40) shareChange += 0.5;
            if (period === 2 && pricingAdj < 0) shareChange += 1.0;
            if (period === 3 && catFocus === 'smart_home') shareChange += 2.0;
            ds.marketShare = Math.round(Math.max(8, Math.min(35, ds.marketShare + shareChange)) * 10) / 10;

            var satChange = (storeInv - 5) * 2 + (stockEff.availability - 0.96) * 30;
            if (pricingAdj < -3) satChange -= 2;
            if (vendorStrat === 'exclusive') satChange += 3;
            ds.customerSatisfaction = Math.round(Math.max(40, Math.min(100, ds.customerSatisfaction + satChange)));

            ds.onlinePenetration = Math.round(onlinePenetrationCalc * 10) / 10;

            ds.inventoryTurnover = Math.round((5.0 + stockEff.turnoverAdj + (revenue / baseRevenue - 1) * 2) * 10) / 10;
            ds.markdownRate = Math.round(Math.max(8, Math.min(30, 18 + stockEff.markdownAdj * 100 + (pricingAdj > 3 ? 3 : 0))) * 10) / 10;
            ds.sellThrough = Math.round(Math.max(50, Math.min(92, 70 + (stockEff.availability - 0.96) * 50 + (pricingAdj < 0 ? 3 : -2))) * 10) / 10;
            ds.gmroi = Math.round(grossMarginPct * ds.inventoryTurnover * 100 / 0.38);

            var crpiGM = Math.min(30, (grossMargin / 3500000) * 30);
            var crpiRevGrowth = Math.min(20, Math.max(0, ((revenue / baseRevenue) - 1) * 100 + 10) * 0.20);
            var crpiShare = (ds.marketShare / 35) * 20;
            var crpiGmroi = Math.min(15, (ds.gmroi / 400) * 15);
            var crpiSat = (ds.customerSatisfaction / 100) * 10;
            var crpiOnline = Math.min(5, (ds.onlinePenetration / 40) * 5);

            var crpiScore = Math.round((crpiGM + crpiRevGrowth + crpiShare + crpiGmroi + crpiSat + crpiOnline) * 10) / 10;

            if (ds.inventoryTurnover < 2 || ds.markdownRate > 25) {
                crpiScore = Math.max(0, crpiScore - 5);
            }

            ds.crpiScore = crpiScore;

            ds.revenueHistory.push(revenue);
            ds.marginHistory.push(grossMargin);
            ds.marketShareHistory.push(ds.marketShare);
            ds.crpiHistory.push(crpiScore);
            ds.satisfactionHistory.push(ds.customerSatisfaction);
            ds.onlinePenHistory.push(ds.onlinePenetration);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: period,
                revenue: revenue,
                grossMargin: grossMargin,
                grossMarginPct: Math.round(grossMarginPct * 1000) / 10,
                operatingCosts: totalOpCost,
                netProfit: netProfit,
                marketShare: ds.marketShare,
                crpiScore: crpiScore,
                customerSatisfaction: ds.customerSatisfaction,
                onlinePenetration: ds.onlinePenetration,
                inventoryTurnover: ds.inventoryTurnover,
                markdownRate: ds.markdownRate,
                sellThrough: ds.sellThrough,
                gmroi: ds.gmroi
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('marginDisplay', 'domainState.totalGrossMargin',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('shareDisplay', 'domainState.marketShare',
                function(v) { return v + '%'; });
            uiManager.bind('crpiDisplay', 'domainState.crpiScore');
            uiManager.bind('satisfactionDisplay', 'domainState.customerSatisfaction');
            uiManager.bind('onlineDisplay', 'domainState.onlinePenetration',
                function(v) { return v + '%'; });
            uiManager.bind('gmroiDisplay', 'domainState.gmroi');
            uiManager.bind('turnoverDisplay', 'domainState.inventoryTurnover');
            uiManager.bind('markdownDisplay', 'domainState.markdownRate',
                function(v) { return v + '%'; });
            uiManager.bind('sellthroughDisplay', 'domainState.sellThrough',
                function(v) { return v + '%'; });
        }

        getChartConfig() {
            return {
                financialChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Revenue ($)',
                                data: [],
                                backgroundColor: 'rgba(26,35,126,0.7)',
                                borderColor: '#1a237e',
                                borderWidth: 2
                            },
                            {
                                label: 'Gross Margin ($)',
                                data: [],
                                backgroundColor: 'rgba(76,175,80,0.7)',
                                borderColor: '#4caf50',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Financial Performance by Round' }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                },
                marketChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Market Share (%)',
                                data: [],
                                borderColor: '#e91e63',
                                backgroundColor: 'rgba(233,30,99,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'CRPI Score',
                                data: [],
                                borderColor: '#ff9800',
                                backgroundColor: 'rgba(255,152,0,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Market Position and CRPI Score' }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                display: true,
                                position: 'left',
                                beginAtZero: true,
                                max: 40,
                                title: { display: true, text: 'Market Share (%)' }
                            },
                            y1: {
                                type: 'linear',
                                display: true,
                                position: 'right',
                                beginAtZero: true,
                                max: 100,
                                title: { display: true, text: 'CRPI Score' },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.marginHistory }
                    ]
                },
                marketChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.marketShareHistory },
                        { data: state.domainState.crpiHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalRevenue = 0;
            var totalMargin = 0;
            var totalProfit = 0;
            var lastCRPI = 0;
            var lastShare = 20;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalRevenue += r.revenue || 0;
                totalMargin += r.grossMargin || 0;
                totalProfit += r.netProfit || 0;
                lastCRPI = r.crpiScore || 0;
                lastShare = r.marketShare || 20;
            }

            var avgMarginPct = totalRevenue > 0 ? (totalMargin / totalRevenue * 100) : 0;
            var performance = 'Developing Retailer';
            if (lastCRPI >= 70 && lastShare >= 24) performance = 'Market Leader';
            else if (lastCRPI >= 55 && lastShare >= 20) performance = 'Strong Competitor';
            else if (lastCRPI >= 40) performance = 'Solid Operator';

            var insights = [];
            if (lastShare >= 25) insights.push('Excellent market share growth - your competitive positioning was effective.');
            if (lastShare < 18) insights.push('Market share declined - review pricing and assortment alignment with customer preferences.');
            if (avgMarginPct >= 40) insights.push('Strong gross margin discipline - good pricing and category management.');
            if (avgMarginPct < 32) insights.push('Margin compression detected - balance volume pursuit with profitability targets.');
            if (totalProfit > 2000000) insights.push('Healthy cumulative profit - operations and investment well balanced.');
            if (totalProfit < 500000) insights.push('Low profitability - consider reducing operational costs or improving revenue mix.');

            return {
                totalRevenue: totalRevenue,
                totalGrossMargin: totalMargin,
                totalNetProfit: totalProfit,
                avgMarginPct: Math.round(avgMarginPct * 10) / 10,
                finalCRPI: lastCRPI,
                finalMarketShare: lastShare,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.netProfit < 0) return window.mySimulation.t('hint_loss');
            if (results.marketShare < 16) return window.mySimulation.t('hint_share_low');
            if (results.markdownRate > 24) return window.mySimulation.t('hint_markdown_high');
            if (results.inventoryTurnover < 3) return window.mySimulation.t('hint_turnover_low');
            if (results.grossMarginPct > 42) return window.mySimulation.t('hint_margin_strong');
            if (state.currentPeriod === 2) return window.mySimulation.t('hint_pricewar');
            if (state.currentPeriod === 3) return window.mySimulation.t('hint_newcategory');
            return null;
        }

